export const CLAIM_NUMBER = /^([1-9]\d{0,8}|.{1,200}-[1-9]\d{0,8})$/;

/** Whether the claim is a correction: its amount is negative. */
export function isCorrection(claim: ClaimView): boolean {
  return cents(claim.amount) < 0;
}

